SELECT COUNT(*) FROM biz_lecturer
 WHERE deleted = FALSE
   AND pool_state = #{poolState}
   AND training_state = #{trainingState}

SELECT COUNT(*) FROM biz_training_plan
 WHERE deleted = FALSE
   AND plan_start_date <= #{rangeEnd}
   AND plan_end_date >= #{rangeStart}

SELECT COUNT(*) FROM biz_training_session
 WHERE deleted = FALSE
   AND session_state = #{sessionState}
   AND last_state_changed_at < #{before}

SELECT COUNT(*) FROM biz_training_session
 WHERE deleted = FALSE
   AND training_date >= #{monthStart}
   AND training_date <= #{monthEnd}

SELECT COUNT(*) FROM dtl_attendance a
  JOIN biz_training_session s ON s.id = a.session_id AND s.deleted = FALSE
 WHERE a.attend_status = #{attendStatus}
   AND s.training_date >= #{monthStart}
   AND s.training_date <= #{monthEnd}

SELECT COUNT(*) FROM dtl_attendance a
  JOIN biz_training_session s ON s.id = a.session_id AND s.deleted = FALSE
 WHERE a.attend_status = #{attendStatus}
   AND s.training_date < #{before}

SELECT COUNT(*) FROM sys_task
 WHERE deleted = FALSE
   AND task_type = #{taskType}
   AND task_state IN
   #{s}

SELECT COUNT(*) FROM biz_training_session
 WHERE deleted = FALSE
   AND training_date >= #{monthStart}
   AND training_date <= #{monthEnd}
   AND session_state IN
   #{s}

SELECT COUNT(DISTINCT lecturer_id) FROM biz_training_session
 WHERE deleted = FALSE
   AND lecturer_id IS NOT NULL
   AND training_date >= #{sinceDate}
   AND session_state IN
   #{s}
